  const bytes = data => (JSON.stringify(data).length+KEY.length)*2;
  function budget(data){if(bytes(data)>4*MIB)fail('Превышен бюджет 4 МиБ. Данные не изменены. Скачайте резервную копию и уменьшите крупные описания.');}
