  function grouped(tasks,day=today()){const active=tasks.filter(t=>t.status!=='Готово');const end=addDays(day,7);const sort=(a,b)=>a.dueDate.localeCompare(b.dueDate)||priorities.indexOf(a.priority)-priorities.indexOf(b.priority)||a.createdAt.localeCompare(b.createdAt);return {overdue:active.filter(t=>t.dueDate<day).sort(sort),important:active.filter(t=>t.dueDate===day&&t.priority==='Высокий').sort(sort),today:active.filter(t=>t.dueDate===day&&t.priority!=='Высокий').sort(sort),soon:active.filter(t=>t.dueDate>day&&t.dueDate<=end).sort(sort),reply:active.filter(t=>t.status==='Нужно ответить').sort(sort),waiting:active.filter(t=>t.status==='Жду ответа клиента').sort(sort)};}
  function linked(data,taskId){return ['timeEntries','clientAccruals','contractorAccruals','fixedSchedules'].some(k=>data[k].some(r=>r.taskId===taskId));}
  function updateTask(previous,next){if(previous?.status==='Готово'&&next.checklist.some(x=>!x.done)&&next.checklist.some(x=>!previous.checklist.some(y=>y.id===x.id)))next.status='В работе';next.completedOn=next.status==='Готово'?(previous?.completedOn||today()):null;return next;}
  /* Денежная модель. Все суммы в копейках, время в целых минутах. */
