  const hourlyAmount=(minutes,rate)=>Math.floor((minutes*rate+30)/60);
  function duration(entry){if(entry.mode==='interval'){const parse=s=>{if(!/^\d{2}:\d{2}$/.test(s||''))fail('Укажите время в формате ЧЧ:ММ.','start');const [h,m]=s.split(':').map(Number);if(h>23||m>59)fail('Неверное время.','start');return h*60+m;};const interval=parse(entry.end)-parse(entry.start);if(interval<=0)fail('Конец должен быть позже начала; через полночь введите две записи.','end');if(!Number.isInteger(entry.breakMinutes)||entry.breakMinutes<0||entry.breakMinutes>=interval)fail('Перерыв должен быть меньше рабочего интервала.','breakMinutes');return interval-entry.breakMinutes;}if(entry.mode!=='duration'||!Number.isInteger(entry.durationMinutes)||entry.durationMinutes<1||entry.durationMinutes>1440)fail('Длительность должна быть от 1 до 1440 минут.','hours');return entry.durationMinutes;}
  function overlaps(data,entry){if(entry.mode!=='interval')return [];const a=entry.start,b=entry.end;return data.timeEntries.filter(e=>e.id!==entry.id&&e.mode==='interval'&&e.date===entry.date&&e.contractorId===entry.contractorId&&a<e.end&&b>e.start);}
  const markedIds=data=>new Set(data.actMarks.flatMap(m=>m.lines.map(l=>l.accrualId)));
  const paidExpense=(data,id)=>data.contractorPayments.reduce((n,p)=>n+p.allocations.filter(a=>a.accrualId===id).reduce((s,a)=>s+a.amountCents,0),0);
  function timeLock(data,id){const marked=markedIds(data);if(data.clientAccruals.some(a=>a.timeEntryId===id&&marked.has(a.id)))return 'Время включено в выставленный акт. Сначала снимите отметку выставления.';if(data.contractorAccruals.some(a=>a.timeEntryId===id&&paidExpense(data,a.id)>0))return 'По этим часам уже была выплата подрядчику. Сначала отмените выплату.';return '';}
  function fixedLock(data,taskId){const ids=markedIds(data);return data.clientAccruals.some(a=>a.taskId===taskId&&ids.has(a.id));}
  function splitFixed(total,first,last){const list=months(first,last),part=Math.floor(total/list.length);return list.map((month,i)=>({month,amountCents:part+(i===list.length-1?total-part*list.length:0)}));}
