    const marked=markedIds(data),oldClient=new Map(data.clientAccruals.map(a=>[a.sourceKey,a])),oldCost=new Map(data.contractorAccruals.map(a=>[a.sourceKey,a]));const incoming=[],costs=[];
    const clientRow=(key,fields)=>{const old=oldClient.get(key);if(old&&marked.has(old.id)){incoming.push(old);return;}let values={...fields,sourceKey:key};if(old?.manualOverride&&fields.model==='subscription')values={...values,amountCents:old.amountCents,manualOverride:true,correctionNote:old.correctionNote};if(old){const merged={...old,...values};if(JSON.stringify(merged)!==JSON.stringify(old))merged.updatedAt=new Date().toISOString();incoming.push(merged);}else incoming.push(stamp({...values,manualOverride:false,correctionNote:''}));};
    const costRow=(key,fields)=>{const old=oldCost.get(key);if(old&&paidExpense(data,old.id)>0){costs.push(old);return;}const merged=old?{...old,...fields,sourceKey:key}:stamp({...fields,sourceKey:key});if(old&&JSON.stringify(merged)!==JSON.stringify(old))merged.updatedAt=new Date().toISOString();costs.push(merged);};
    const details=t=>({clientId:t.clientId,projectId:t.projectId||null,taskId:t.id,serviceId:t.serviceId||null,contractId:t.contractId||null,name:t.actName||serviceMap.get(t.serviceId)?.name||t.name});
    for(const e of data.timeEntries){const t=taskMap.get(e.taskId);if(!t)continue;if(e.billable&&t.model==='hourly')clientRow('time:'+e.id,{...details(t),model:'hourly',timeEntryId:e.id,periodStart:e.date,periodEnd:e.date,recognitionDate:e.date,durationMinutes:e.durationMinutes,rateCents:e.saleRateCents,amountCents:hourlyAmount(e.durationMinutes,e.saleRateCents),isPlanned:e.date>day});const term=termMap.get(e.contractorTermId);if(term?.type==='hourly')costRow('time:'+e.id,{taskId:t.id,contractorId:e.contractorId,termId:term.id,timeEntryId:e.id,date:e.date,amountCents:hourlyAmount(e.durationMinutes,e.costRateCents)});}
    for(const t of data.tasks){if(t.model!=='fixed')continue;if(t.fixedMethod==='completion'&&t.status==='Готово')clientRow('fixed:'+t.id,{...details(t),model:'fixed',timeEntryId:null,periodStart:t.completedOn,periodEnd:t.completedOn,recognitionDate:t.completedOn,durationMinutes:null,rateCents:null,amountCents:t.fixedCents,isPlanned:t.completedOn>day});if(t.fixedMethod==='monthly')for(const s of data.fixedSchedules.filter(x=>x.taskId===t.id))clientRow('fixed:'+t.id+':'+s.month,{...details(t),model:'fixed',timeEntryId:null,periodStart:s.month+'-01',periodEnd:monthEnd(s.month),recognitionDate:monthEnd(s.month),durationMinutes:null,rateCents:null,amountCents:s.amountCents,isPlanned:monthEnd(s.month)>day});}
    for(const s of data.services){if(s.model!=='subscription'||!s.startDate||s.startDate>day)continue;const last=(s.endDate&&s.endDate<day?s.endDate:day).slice(0,7);for(const month of months(s.startDate.slice(0,7),last)){const start=s.startDate>month+'-01'?s.startDate:month+'-01',end=s.endDate&&s.endDate<monthEnd(month)?s.endDate:monthEnd(month);if(start>end)continue;const days=Number(end.slice(-2))-Number(start.slice(-2))+1;const price=s.prices.filter(p=>p.month<=month).sort((a,b)=>b.month.localeCompare(a.month))[0];if(!price)continue;const amount=Math.floor((price.amountCents*days+Number(monthEnd(month).slice(-2))/2)/Number(monthEnd(month).slice(-2)));clientRow('subscription:'+s.id+':'+month,{clientId:s.clientId,projectId:s.projectId||null,taskId:null,serviceId:s.id,contractId:s.contractId||null,name:s.name,model:'subscription',timeEntryId:null,periodStart:start,periodEnd:end,recognitionDate:end,durationMinutes:null,rateCents:null,amountCents:amount,isPlanned:end>day});}}
